		}
		checkpointPath := taskMetadataDir + "/checkpoint.json"
		changes.addFile(checkpointPath, blobHash, filemode.Regular)
	}

	// Apply changes incrementally to the base tree
	return applyChangesToTree(s.repo, baseTreeHash, changes)
}

