    ModifiedFiles:       changes.Modified,  // <-- USED HERE
    NewFiles:            changes.New,
    DeletedFiles:        changes.Deleted,
    // ...
}
```

**Summary:** The `Modified` field is populated but discarded in main checkpoints, used only for task/incremental checkpoints.

