		ModifiedFiles:            relModifiedFiles,
		NewFiles:                 relNewFiles,
		DeletedFiles:             relDeletedFiles,
		CommitMessage:            commitMessage,
		TranscriptPath:           transcriptPath,
		AuthorName:               author.Name,
		AuthorEmail:              author.Email,
		AgentType:                agentType,
		StepTranscriptIdentifier: transcriptIdentifierAtStart,
		StepTranscriptStart:      transcriptLinesAtStart,
	}

	if err := strat.SaveChanges(ctx); err != nil {
		return fmt.Errorf("failed to save changes: %w", err)
	}

	// Update session state with new transcript position for auto-commit strategy.
	// Auto-commit needs this to avoid re-parsing old transcript lines on subsequent checkpoints.
	// Manual-commit tracks position per-step via pre-prompt state.
	if strat.Name() == strategy.StrategyNameAutoCommit {
		sessionState, loadErr := strategy.LoadSessionState(sessionID)
